/* Research context from processed Scopus metadata; no citation inference. */
(() => {
  'use strict';
  const section=document.querySelector('#landscape');
  if(!section)return;
  const $=selector=>section.querySelector(selector);
  const make=(tag,className,text)=>{const el=document.createElement(tag);if(className)el.className=className;if(text!==undefined)el.textContent=text;return el;};
  const format=value=>Number(value).toLocaleString('en-US');
  const displayAuthors=authors=>authors.replace(/\s*\(\d{6,}\)/g,'');
  const base=new URL('assets/landscape/',document.baseURI);
  const positions={digital:[100,70],adoption:[320,55],behavior:[540,80],support:[100,235],knowledge:[320,245],networks:[540,230]};
  const state={data:null,selected:'digital',preview:null,loading:false,detailRequest:0,panelRequest:0,page:0,filter:'digital',opener:null,mounted:false,mode:'themes'};
  const chunkCache=new Map(),pageSize=12,dialog=$('#rl-literature');
  let hoverTimer=0;
  const theme=id=>state.data.themes.find(item=>item.id===id);
  async function getJSON(url){const response=await fetch(url);if(!response.ok)throw new Error('Metadata unavailable');return response.json();}
  async function paperAt(address){const filename=state.data.publicFiles[address[0]];if(!/^papers-[a-f0-9]{12}\.json$/.test(filename))throw new Error('Invalid paper metadata reference');if(!chunkCache.has(filename))chunkCache.set(filename,getJSON(new URL(filename,base)).catch(error=>{chunkCache.delete(filename);throw error;}));const chunk=await chunkCache.get(filename);const paper=chunk[address[1]];if(!paper)throw new Error('Missing paper metadata');return paper;}
  function focusMap(id){const neighbors=new Set([id]);state.data.edges.forEach(edge=>{if(edge.source===id)neighbors.add(edge.target);if(edge.target===id)neighbors.add(edge.source);});$('#rl-map').classList.add('has-focus');section.querySelectorAll('.rl-node').forEach(button=>{const key=button.dataset.theme;button.setAttribute('aria-pressed',String(key===state.selected));button.classList.toggle('is-related',key!==id&&neighbors.has(key));button.classList.toggle('is-unrelated',!neighbors.has(key));});section.querySelectorAll('.rl-edge').forEach(edge=>edge.classList.toggle('is-related',edge.dataset.from===id||edge.dataset.to===id));}
  function selectTheme(id){if(state.mode==='gap')setMode('themes');clearTimeout(hoverTimer);state.selected=id;state.preview=null;showTheme(id);}
  function buildGraph(){const svg=$('#rl-edges'),nodes=$('#rl-nodes');svg.replaceChildren();nodes.replaceChildren();for(const edge of state.data.edges){const line=document.createElementNS('http://www.w3.org/2000/svg','line');const a=positions[edge.source],b=positions[edge.target];line.classList.add('rl-edge');line.dataset.from=edge.source;line.dataset.to=edge.target;line.setAttribute('x1',a[0]);line.setAttribute('y1',a[1]);line.setAttribute('x2',b[0]);line.setAttribute('y2',b[1]);line.style.setProperty('--edge-width',(.7+edge.jaccard*2).toFixed(2));line.style.setProperty('--edge-opacity',(.13+edge.jaccard*.5).toFixed(2));svg.append(line);}
    for(const item of state.data.themes){const button=make('button','rl-node');button.dataset.theme=item.id;button.setAttribute('aria-pressed',String(item.id===state.selected));button.setAttribute('aria-label',item.label+', '+format(item.count)+' matching records');button.style.left=positions[item.id][0]/6.4+'%';button.style.top=positions[item.id][1]/3+'%';button.append(make('span','rl-node-dot'),make('span','rl-node-label',item.short),make('span','rl-node-count',format(item.count)+' records'));button.addEventListener('click',()=>selectTheme(item.id));button.addEventListener('pointerenter',event=>{if(event.pointerType!=='mouse'||state.mode==='gap')return;clearTimeout(hoverTimer);hoverTimer=setTimeout(()=>{state.preview=item.id;showTheme(item.id);},100);});button.addEventListener('pointerleave',()=>{clearTimeout(hoverTimer);state.preview=null;showTheme(state.selected);});button.addEventListener('focus',()=>{state.preview=item.id;showTheme(item.id);});button.addEventListener('blur',()=>{state.preview=null;showTheme(state.selected);});nodes.append(button);}}
  async function showTheme(id){if(!state.data||state.mode==='gap')return;const item=theme(id),request=++state.detailRequest;focusMap(id);$('#rl-theme-title').textContent=item.label;$('#rl-theme-count').textContent=format(item.count)+' records match this theme. Matches reflect terminology, not an assessment of study findings.';const terms=$('#rl-theme-terms');terms.replaceChildren(...[...item.terms].sort((a,b)=>b.count-a.count).slice(0,5).map(term=>{const chip=make('span','rl-term',term.term);chip.title=format(term.count)+' records match this term.';return chip;}));const related=$('#rl-related');related.replaceChildren(make('span','rl-small-label','SHARED RECORDS WITH '+item.label.toUpperCase()));state.data.allEdges.filter(edge=>edge.source===id||edge.target===id).sort((a,b)=>b.shared-a.shared).forEach(edge=>{const other=edge.source===id?edge.target:edge.source,button=make('button','',theme(other).label+' · '+format(edge.shared)+' shared records');button.addEventListener('click',()=>selectTheme(other));related.append(button);});
    const preview=$('#rl-paper-preview');preview.replaceChildren(make('p','','Loading related literature...'));try{const papers=await Promise.all(state.data.lists[id].slice(0,1).map(paperAt));if(request!==state.detailRequest)return;preview.replaceChildren(...papers.map(paper=>{const button=make('button','');button.append(make('span','rl-preview-title',paper.title),make('small','rl-preview-authors',displayAuthors(paper.authors)||'Authors unavailable'),make('small','',(paper.year||'Year unavailable')+(paper.source?' · '+paper.source:'')));button.addEventListener('click',()=>openLiterature(id,paper.id));return button;}));}catch{if(request!==state.detailRequest)return;preview.replaceChildren(make('p','','Related literature could not load. Open the literature panel to try again.'));}}
  function buildContext(){const d=state.data;const corpus=$('#rl-corpus');corpus.replaceChildren(...[[d.screenedRecords,'construction-context records'],[d.themes.length,'themes'],[d.fileCount,'Scopus searches']].map(([value,label])=>{const span=make('span','');span.append(make('strong','',format(value)+' '),document.createTextNode(label));return span;}));const methods=$('#rl-methodology');const texts=[
format(d.inputRows)+' Scopus entries were consolidated into '+format(d.uniqueRecords)+' unique records. A term-based construction-context screen retained '+format(d.screenedRecords)+'; '+format(d.excludedByContext)+' were outside that scope. '+format(d.unassigned)+' records do not match the six themes and remain available in the literature panel. The collection combines '+format(d.fileCount)+' Scopus search exports, including overlapping and filtered results.',
'Screening uses construction-related terms in titles and keywords, or an explicit construction context in abstracts. It is not a full-text eligibility review: incidental matches may remain, and exclusions do not establish a literature gap.',
'The six themes group recurring terms in titles, abstracts, author keywords and indexed keywords. Membership is assigned by phrase matching rather than full-text interpretation of theories or findings. Each term occurs in at least '+d.minimumTermDocuments+' records. Case and hyphen variants are matched, and a record may belong to several themes.',
'Lines connect themes found in the same records. Each record counts once per theme pair. These links represent shared terminology, not citations, causality or shared findings.',
'The theme view shows up to 8 links supported by at least 3 shared records, ranked by Jaccard overlap (intersection / union). GAP shows all nonzero overlaps. Node positions aid reading rather than represent statistical distances; record counts do not measure the importance of a research field.',
'Author keywords and indexed keywords are shown separately. Matches from titles and abstracts retain their field labels. References and citation counts are not used to construct the map. Duplicate detection uses DOI, EID, or matching title, year and authors. Study findings were not assessed through full-text review.'
];methods.replaceChildren(...texts.map(text=>make('p','',text)));const version=make('p','','Collection reference: ');version.append(make('code','',d.corpusVersion));methods.append(version);$('#rl-observations').replaceChildren(...[d.observations[1],d.observations[2]].map(item=>make('p','',item.text)));
    const approved=d.approvedGaps.find(item=>item.display);
    if(approved){
      section.dataset.gapApproved='true';
      for(const element of section.querySelectorAll('[data-gap-copy]'))element.textContent=element.dataset.gapCopy==='text'?approved.text:approved.display[element.dataset.gapCopy];
      $('#rl-gap-status').textContent='Practical support beyond TPB';
    }
    const filter=$('#rl-filter');filter.replaceChildren(make('option','','All construction-context records'));filter.firstElementChild.value='all';if(approved?.literatureExamples?.length){const examples=make('option','','Related studies ('+approved.literatureExamples.length+')');examples.value='prior-integration';filter.append(examples);}for(const item of d.themes){const option=make('option','',item.label+' ('+format(item.count)+')');option.value=item.id;filter.append(option);}const other=make('option','','Other construction-context records ('+format(d.unassigned)+')');other.value='unassigned';filter.append(other);}
  function sourceLink(paper){if(/^10\.\d{4,9}\/\S+$/i.test(paper.doi))return 'https://doi.org/'+encodeURIComponent(paper.doi).replace(/%2F/gi,'/');try{const url=new URL(paper.link);return url.protocol==='https:'||url.protocol==='http:'?url.href:null;}catch{return null;}}
  function paperCard(paper,expandId){const card=make('article','rl-record');card.dataset.paper=paper.id;card.append(make('span','',paper.year?String(paper.year):'Year unavailable'),make('h4','',paper.title),make('p','rl-authors',displayAuthors(paper.authors)||'Authors unavailable'),make('p','',paper.source||'Publication unavailable'));const detail=make('details',''),summary=make('summary','','Keywords & theme connections +');detail.append(summary);let rendered=false;detail.addEventListener('toggle',()=>{if(!detail.open||rendered)return;rendered=true;detail.append(make('p','rl-meta-label','Authors'),make('p','',paper.authors||'Unavailable'),make('p','rl-meta-label','Author keywords'),make('p','',paper.authorKeywords.length?paper.authorKeywords.join('; '):'Unavailable'),make('p','rl-meta-label','Indexed keywords'),make('p','',paper.indexKeywords.length?paper.indexKeywords.join('; '):'Unavailable'));const evidence=make('div','rl-evidence');if(!paper.themes.length)evidence.append(make('p','','Not assigned to these six themes; related concepts may still appear in the study.'));for(const id of paper.themes){evidence.append(make('p','rl-meta-label',theme(id).label));for(const item of paper.evidence[id])evidence.append(make('p','',item.field+': '+[...new Set(item.matches.map(match=>match.matchedText))].join('; ')));}detail.append(evidence);const href=sourceLink(paper);if(href){const link=make('a','rl-paper-link',paper.doi?'View DOI record \u2197':'View publication \u2197');link.href=href;link.target='_blank';link.rel='noopener noreferrer';detail.append(link);}});const context=state.data.approvedGaps.find(item=>item.display)?.literatureExamples?.find(item=>item.id===paper.id)?.contextNote;if(state.filter==='prior-integration'&&context)card.append(make('p','rl-example-context',context));card.append(detail);if(paper.id===expandId)detail.open=true;return card;}
  async function renderPage(expandId){const request=++state.panelRequest,addresses=state.filter==='prior-integration'?(state.data.approvedGaps.find(item=>item.display)?.literatureExamples||[]).map(item=>item.address):(state.data.lists[state.filter]||[]),total=addresses.length,maxPage=Math.max(0,Math.ceil(total/pageSize)-1);state.page=Math.min(state.page,maxPage);const start=state.page*pageSize;$('#rl-dialog-description').textContent=state.filter==='prior-integration'?'Selected studies connecting behavioral and relational perspectives, including related virtual-team research. Open a record to explore its keywords and theme connections.':'Explore the Scopus literature. Open a record to see its keywords and connections to the themes.';$('#rl-result-count').textContent=format(total)+(state.filter==='prior-integration'?' selected studies':' records · newest year first');$('#rl-page-number').textContent='Page '+(state.page+1)+' of '+(maxPage+1);$('#rl-prev').disabled=true;$('#rl-next').disabled=true;const container=$('#rl-records');container.replaceChildren(make('p','rl-dialog-error','Loading the literature…'));try{const papers=await Promise.all(addresses.slice(start,start+pageSize).map(paperAt));if(request!==state.panelRequest)return;container.replaceChildren(...papers.map(p=>paperCard(p,expandId)));if(!papers.length)container.append(make('p','','No records match this theme.'));$('#rl-prev').disabled=state.page===0;$('#rl-next').disabled=state.page>=maxPage;}catch{if(request!==state.panelRequest)return;const retry=make('button','button secondary','Try again');retry.addEventListener('click',()=>renderPage(expandId));container.replaceChildren(make('p','rl-dialog-error','The literature could not load. Your selected theme is unchanged.'),retry);}}
  function openLiterature(filter=state.preview||state.selected,expandId){state.filter=filter;state.page=0;$('#rl-filter').value=filter;state.opener=document.activeElement;if(!dialog.open)dialog.showModal();renderPage(expandId);}
  $('#rl-open-literature').addEventListener('click',()=>openLiterature());$('#rl-close-literature').addEventListener('click',()=>dialog.close());dialog.addEventListener('close',()=>{state.panelRequest++;(state.opener?.isConnected?state.opener:$("#rl-open-literature")).focus({preventScroll:true});});dialog.addEventListener('click',event=>{if(event.target!==dialog)return;const r=dialog.getBoundingClientRect();if(event.clientX<r.left||event.clientX>r.right||event.clientY<r.top||event.clientY>r.bottom)dialog.close();});$('#rl-filter').addEventListener('change',event=>{state.filter=event.target.value;state.page=0;renderPage();});$('#rl-prev').addEventListener('click',()=>{state.page=Math.max(0,state.page-1);renderPage();dialog.scrollTo({top:0,behavior:'instant'});});$('#rl-next').addEventListener('click',()=>{state.page++;renderPage();dialog.scrollTo({top:0,behavior:'instant'});});
  async function load(){if(state.loading||state.mounted)return;state.loading=true;const status=$('#rl-load-status');status.textContent='Loading the research landscape…';try{const response=await fetch(new URL('summary.json',base),{cache:'no-cache'});if(!response.ok)throw new Error('Summary unavailable');const data=await response.json();if(data.schemaVersion!==1||!Array.isArray(data.themes)||!data.themes.every(t=>positions[t.id]))throw new Error('Unsupported map data');state.data=data;buildGraph();buildContext();$('#rl-content').hidden=false;$('#rl-open-literature').disabled=false;state.mounted=true;section.dataset.initialized='true';status.hidden=true;showTheme(state.selected);}catch{state.mounted=false;status.hidden=false;status.textContent='The map is available, but the literature could not load. ';const retry=make('button','','Retry');retry.addEventListener('click',load);status.append(retry);}finally{state.loading=false;}}

  // GAP is an author-interpretation view over the same saved theme evidence.
  function setMode(mode){
    if(!state.data?.approvedGaps.some(item=>item.display))return;
    clearTimeout(hoverTimer);state.detailRequest++;state.preview=null;state.mode=mode;
    section.dataset.landscapeMode=mode;
    section.querySelectorAll('[data-landscape-mode]').forEach(button=>button.setAttribute('aria-pressed',String(button.dataset.landscapeMode===mode)));
    const active=mode==='gap';
    $('#rl-gap-question').hidden=!active;$('#rl-gap-detail').hidden=!active;$('#rl-gap-map-note').hidden=!active;
    $('#rl-map').classList.toggle('has-gap',active);
    for(const node of section.querySelectorAll('.rl-node'))node.classList.toggle('rl-gap-relevant',active&&['behavior','knowledge','networks','support'].includes(node.dataset.theme));
    section.querySelectorAll('.rl-gap-edge').forEach(edge=>edge.remove());
    if(active){
      $('#rl-map').classList.remove('has-focus');
      const displayed=new Set(state.data.edges.map(edge=>edge.source+':'+edge.target));
      for(const edge of state.data.allEdges){
        if(!edge.shared||displayed.has(edge.source+':'+edge.target))continue;
        const line=document.createElementNS('http://www.w3.org/2000/svg','line');
        const a=positions[edge.source],b=positions[edge.target];
        line.classList.add('rl-edge','rl-gap-edge');line.dataset.from=edge.source;line.dataset.to=edge.target;
        for(const [key,value]of Object.entries({x1:a[0],y1:a[1],x2:b[0],y2:b[1]}))line.setAttribute(key,value);
        const title=document.createElementNS('http://www.w3.org/2000/svg','title');title.textContent=edge.shared+' shared records; Jaccard '+edge.jaccard.toFixed(4);line.append(title);$('#rl-edges').append(line);
      }
    }else showTheme(state.selected);
  }
  section.querySelectorAll('.rl-mode [data-landscape-mode]').forEach(button=>button.addEventListener('click',()=>setMode(button.dataset.landscapeMode)));
  $('#rl-gap-question').addEventListener('click',()=>$('#rl-gap-detail').focus({preventScroll:true}));
  section.addEventListener('click',event=>{if(event.target.closest('#rl-gap-literature'))openLiterature('prior-integration');});

  // The small summary initializes immediately; paper batches still load on demand.
  load();
})();
